/**
 * close serialport
 * Java: `DeviceServiceManager.getSerialPort(int)`
 * @param index selects the hardware slot (0-based).
 */
export const serialport = (index: number) => ({
  /**
   * open serialport
   * @returns true:success,false:failed
   */
  open: (): Effect.Effect<boolean, TopwiseError, TopwiseBridge> =>
    call("serialport", index, "open", []),

  /**
   * init serialport
   * @param baudratebyte the baudrate of serialport
   * @param dataBits data bits
   * @param parity Check bit,default value is 0x00
   * @param StopBits Stop bit,default value is 0x00
   * @returns true:success,false:failed
   */
  init: (baudratebyte: number, dataBits: number, parity: number, StopBits: number): Effect.Effect<boolean, TopwiseError, TopwiseBridge> =>
    call("serialport", index, "init", [baudratebyte, dataBits, parity, StopBits]),

  /**
   * send data
   * @param data send data
   * @param timeout time out(ms)
   * @returns true:success,false:failed
   */
  sendData: (data: Uint8Array, timeout: number): Effect.Effect<boolean, TopwiseError, TopwiseBridge> =>
    call("serialport", index, "sendData", [data, timeout]),

  /**
   * read data
   * @param timeout time out(ms)
   * @returns Data read if success, null if failed
   */
  readData: (timeout: number): Effect.Effect<Uint8Array, TopwiseError, TopwiseBridge> =>
    call("serialport", index, "readData", [timeout]),

  /**
   * close serialport
   * @returns true:success,false:failed
   */
  close: (): Effect.Effect<boolean, TopwiseError, TopwiseBridge> =>
    call("serialport", index, "close", []),
});

