/**
 * Add a new CA public key.
 * Java: `DeviceServiceManager.getL2Dpas()`
 */
export const dpas = {
  /**
   * DPAS kernel initialization
   * @returns EMV_OK Initialization completed.
   */
  initialize: (): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "initialize", []),

  /**
   * Query the version number of DPAS kernel.
   * @param pacVer [output] Version number.For example V100 2020.09.01 (rear part is date).
   * @param uiSize [input] The maximum length of pacVer is greater than or equal to 20bytes.
   * @returns EMV_OK Initialization completed. CLSS_PARAM_ERR Parameter error.
   */
  getVersion: (pacVer: Uint8Array, uiSize: number): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "getVersion", [pacVer, uiSize]),

  /**
   * Set several data elements into kernel at one time.
   * @param pacTlvData [input] The data elements list with TLV format.
   * @param unDataLen [input] The Length of pucTLVData.
   * @returns EMV_OK Successful. CLSS_PARAM_ERR Parameter error.(Null pointer) EMV_DATA_ERR Data error found.
   */
  setTLVDataList: (pacTlvData: Uint8Array, unDataLen: number): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "setTLVDataList", [pacTlvData, unDataLen]),

  /**
   * Get one data element specified by the tag.
   * @param pacTagList [input] Tag list of EMV standard or extended data. The max length of one tag is 3 bytes and only one tag is allowed at present.
   * @param ucTagListLen [input] The length of pacTagList.
   * @param unExpectDataLen [input] Equal to the max length of pacDataOut.
   * @param pucDataOut [output] The TLV data serial of the data elements specified by pacTagList.
   * @param punActualDataOutLen [output] The actual length of the TLV data serial indicated by pacTagList.
   * @returns EMV_OK Successful. CLSS_PARAM_ERR Parameter error.(Null pointer) EMV_NOT_FOUND Can’t find the tag or no data。
   */
  getTLVDataList: (pacTagList: Uint8Array, ucTagListLen: number, unExpectDataLen: number, pucDataOut: Uint8Array, punActualDataOutLen: ReadonlyArray<number>): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "getTLVDataList", [pacTagList, ucTagListLen, unExpectDataLen, pucDataOut, punActualDataOutLen]),

  /**
   * Add a new CA public key. 1. It is recommended to delete all CA public keys in the kernel at the beginning of each transaction, and set CA public keys according to the requirements of the current application. In this way, the application only needs to set one CA public key at a time. 2. If the public key is already existed, the new key will replace the old one. 3. CA public key is provided by acquire. Sometimes, the key is not assigned with the structure of EMV_CAPK. In this case, the application must convert the public key before add it.
   * @param stCAPK [input] The CA public key. Please refer to “Clss_Define.h” for structure definition of EMV_CAPK.
   * @returns EMV_OK Successful. EMV_SUM_ERR CAPK checksum error.
   */
  addCAPK: (stCAPK: Input<Types.EmvCapk>): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "addCAPK", [stCAPK]),

  /** Delete all CA public keys. It is suggested to call this function to delete all CA Public Keys in kernel at the beginning of each transaction, and set CA Public Key according to current application’s requirement. In this way, application needs to set only one CA Public Key each time. */
  delAllCAPK: (): Effect.Effect<void, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "delAllCAPK", []),

  /**
   * Add a revoked issuer public key certification to certification revocation list.
   * @param stRevocList [input] The pointer of the revoked issuer public key certification. Please refer to “Clss_Define.h” for structure definition of EMV_REVOCLIST.
   * @returns EMV_OK Successful. EMV_OVERFLOW Memory overflow (CLSS library maximum supports 30 revoked issuer public key certifications).
   */
  addRevocList: (stRevocList: Input<Types.EmvRevocList>): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "addRevocList", [stRevocList]),

  /** Delete all revoked issuer public key certifications. */
  delAllRevocList: (): Effect.Effect<void, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "delAllRevocList", []),

  /**
   * Initialize all data elements of kernel and set the data returned from card during final selection. 1. This function should be called after DP_Initialize. 2. After set final select data, application should set parameters according to the AID final selected.
   * @param paucFCI [input] Pointer of data returned from card during final selection
   * @param unFCILen [input] Length of data.
   * @returns EMV_OK Successful. CLSS_PARAM_ERR Parameter error. CLSS_TERMINATE Terminate transaction. CLSS_RESELECT_APP Delete current application from the candidate list, and then execute final selection again to select the next application. CLSS_USE_CONTACT Terminate CLSS transaction and use contact interface to process transaction instead.
   */
  setFinalSelectData: (paucFCI: Uint8Array, unFCILen: number): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "setFinalSelectData", [paucFCI, unFCILen]),

  /**
   * This function includes the processing of GPO. 1. This function should be called after DP_SetFinalSelectData. 2. Application should set the right TTQ and TVR before GPO with pre-process result.
   * @param pucPathTypeOut [output] Transaction Path (it is effective only when EMV_OK is returned). CLSS_TRANSPATH_EMV - DPAS; CLSS_TRANSPATH_MAG - MagStripe CLSS_TRANSPATH_LEGACY - ZIP
   * @returns EMV_OK Successful. CLSS_PARAM_ERR Parameter error. CLSS_TERMINATE Terminate transaction. CLSS_RESELECT_APP Delete current application from the candidate list, and then execute final selection again to select the next application. CLSS_USE_CONTACT Terminate CLSS transaction and use contact interface to process transaction instead.
   */
  gpoProc: (pucPathTypeOut: Uint8Array): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "gpoProc", [pucPathTypeOut]),

  /**
   * Read application data. 1. This function should be called after DP_GPOProc. 2. After this function is performed successfully, application shall check the exception files. And add CAPK and revocation list.
   * @returns EMV_OK Successful. CLSS_TERMINATE Terminate transaction.
   */
  readData: (): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "readData", []),

  /**
   * Offline data authentication. Cardholder Verification. Processing Restriction. Terminal Action Analysis.
   * @param ucExceptFileFlg [input] PAN is present in the exception files.
   * @returns EMV_OK Successful. CLSS_TERMINATE Transaction terminated. CLSS_USE_CONTACT Try another interface. CLSS_TRY_ANOTHER_CARD Try another card. CLSS_DECLINE Transaction should be declined.
   */
  transProc: (ucExceptFileFlg: number): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "transProc", [ucExceptFileFlg]),

  /**
   * Issuer script process, DPAS support only one script 71 or 72. Application should process script after online transaction complete with any script data and while EMV transaction path.
   * @param nCommuStatus [input] Communication Status.
   * @param paucScript [input] Script data.
   * @param pnScriptLen [input] Script data length.
   * @returns EMV_OK Successful. CLSS_PARAM_ERR Parameter error. CLSS_TERMINATE Transaction terminated. CLSS_DECLINE Transaction should be declined.
   */
  issuerUpdateProc: (nCommuStatus: number, paucScript: Uint8Array, pnScriptLen: ReadonlyArray<number>): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "issuerUpdateProc", [nCommuStatus, paucScript, pnScriptLen]),

  /**
   * Get mapped TRACK1 data. Get mapped TRACK2 data Transaction ZIP and D-PAS MS mode only.
   * @param ucTrackFlg [input] Track1 or 2 flag
   * @param paucDataOut [output] Mapped TRACK data.
   * @param pucLenOut [output] Length of mapped TRACK data.
   * @returns EMV_OK Successful. CLSS_PARAM_ERR Parameter error. EMV_NO_DATA Get Track data failed.
   */
  getTrackMapData: (ucTrackFlg: number, paucDataOut: Uint8Array, pucLenOut: ReadonlyArray<number>): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "getTrackMapData", [ucTrackFlg, paucDataOut, pucLenOut]),

  /**
   * Get the debug information.
   * @param nExpAssistInfoLen [input] RFU(0 can be used)
   * @param paucAssistInfo [output] RFU (NULL can be used)
   * @param pnErrorCode [output] The error code.
   * @returns EMV_OK Successful. CLSS_PARAM_ERR Parameters error.
   */
  getDebugInfo: (nExpAssistInfoLen: number, paucAssistInfo: Uint8Array, pnErrorCode: ReadonlyArray<number>): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "getDebugInfo", [nExpAssistInfoLen, paucAssistInfo, pnErrorCode]),

  /**
   * Extend function to set additional information.
   * @param nFlag [input] RFU
   * @param paucDataIn [input] RFU
   * @param nDataInLen [input] RFU
   * @returns EMV_OK Successful. CLSS_PARAM_ERR Parameter error.(Null pointer)
   */
  setExtendFunc: (nFlag: number, paucDataIn: Uint8Array, nDataInLen: number): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "setExtendFunc", [nFlag, paucDataIn, nDataInLen]),

  optFeatCheck: (): Effect.Effect<void, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "optFeatCheck", []),

  /** @param paucDataIn [input] */
  updateDataContProc: (paucDataIn: Uint8Array, nDataInLen: number): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "updateDataContProc", [paucDataIn, nDataInLen]),

  /** @param paucDataIn [input] */
  writeDataStore: (paucDataIn: Uint8Array, nDataInLen: number): Effect.Effect<number, TopwiseError, TopwiseBridge> =>
    call("dpas", -1, "writeDataStore", [paucDataIn, nDataInLen]),
} as const;

